<?php
declare(strict_types=1);
namespace MarketForecast\Tests;
use DateTimeImmutable;use MarketForecast\MarketData\{CompletedMarketBarGuard,DataLeakageException};use PHPUnit\Framework\TestCase;
final class CompletedMarketBarGuardTest extends TestCase{public function testPreviousCompletedBarAccepted():void{(new CompletedMarketBarGuard())->assertAllowed(['time'=>'2026-09-09T20:00:00+00:00'],new DateTimeImmutable('2026-09-10T14:00:00+00:00'));self::assertTrue(true);}public function testCurrentIncompleteRejected():void{$this->expectException(DataLeakageException::class);(new CompletedMarketBarGuard())->assertAllowed(['time'=>'2026-09-10T14:00:00+00:00'],new DateTimeImmutable('2026-09-10T14:30:00+00:00'));}public function testEarlyCloseSessionIsAcceptedAfterCalendarClose():void{(new CompletedMarketBarGuard())->assertAllowed(['time'=>'2026-11-27T17:00:00+00:00'],new DateTimeImmutable('2026-11-27T18:10:00+00:00'));self::assertTrue(true);}public function testAfterCutoffRejected():void{$this->expectException(DataLeakageException::class);(new CompletedMarketBarGuard())->assertAllowed(['time'=>'2026-09-10T15:00:00+00:00'],new DateTimeImmutable('2026-09-10T14:30:00+00:00'));}}
